Use `pg`’s `Pool`, set both connection acquisition and idle/lifetime timeouts, and treat pool-level errors separately from query errors.

```js
// db.js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,
  min: 2,

  // Timeouts
  connectionTimeoutMillis: 5_000,   // wait for a new connection
  idleTimeoutMillis: 30_000,        // close idle clients after 30s
  maxLifetimeSeconds: 60 * 30,      // recycle connections every 30m

  // Useful in short-lived scripts; usually false for APIs
  allowExitOnIdle: false,

  // SSL example for managed Postgres
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

pool.on('error', (err) => {
  // Fired for idle clients if the backend disconnects or network breaks
  console.error('Unexpected PostgreSQL pool error', err);
});

async function query(text, params, opts = {}) {
  const statementTimeoutMs = opts.statementTimeoutMs ?? 10_000;

  const client = await pool.connect();
  try {
    await client.query(`SET statement_timeout = ${statementTimeoutMs}`);
    return await client.query(text, params);
  } catch (err) {
    console.error('PostgreSQL query failed', {
      message: err.message,
      code: err.code,
      text,
    });
    throw err;
  } finally {
    client.release();
  }
}

async function closePool() {
  await pool.end();
}

module.exports = { pool, query, closePool };
```

Usage in an HTTP handler:

```js
const express = require('express');
const { query, closePool } = require('./db');

const app = express();

app.get('/users/:id', async (req, res) => {
  try {
    const result = await query(
      'SELECT id, email FROM users WHERE id = $1',
      [req.params.id],
      { statementTimeoutMs: 3000 }
    );

    if (result.rowCount === 0) {
      return res.status(404).json({ error: 'Not found' });
    }

    res.json(result.rows[0]);
  } catch (err) {
    if (err.code === '57014') {
      return res.status(504).json({ error: 'Database query timed out' });
    }

    res.status(500).json({ error: 'Database error' });
  }
});

process.on('SIGTERM', async () => {
  await closePool();
  process.exit(0);
});
```

Recommended defaults for most Node APIs:
- `max`: `10-20` per process, not per app cluster.
- `connectionTimeoutMillis`: `2000-5000`.
- `idleTimeoutMillis`: `30000`.
- `statement_timeout`: `2000-10000` depending on endpoint.
- `maxLifetimeSeconds`: `900-1800` to avoid stale connections.

Important points:
- Always `release()` clients in `finally`.
- Prefer one shared pool per process.
- Set a server-side query timeout (`statement_timeout`), not just a pool timeout.
- Handle `pool.on('error')` because idle connection failures won’t show up in your request `try/catch`.
- If you run multiple Node processes, total DB connections = `pool max * process count`.

