Use `pg` built-in pool. Set three timeout layers:

- `connectionTimeoutMillis`: fail fast when pool cannot open new DB connection
- `idleTimeoutMillis`: close unused clients
- `statement_timeout` / `query_timeout`: stop slow queries

Example:

```js
// db.js
import { Pool } from 'pg'

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,
  min: 2,

  // Timeouts
  connectionTimeoutMillis: 2_000,
  idleTimeoutMillis: 30_000,
  statement_timeout: 10_000,
  query_timeout: 10_000,
  idle_in_transaction_session_timeout: 15_000,
  lock_timeout: 5_000,

  // Connection lifecycle
  maxLifetimeSeconds: 300,

  // Useful for scripts/tests, usually false for servers
  allowExitOnIdle: false,

  // TLS in production if required
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
})

// Required: catch background errors from idle clients
pool.on('error', (err) => {
  console.error('Unexpected idle PostgreSQL client error', err)
})
```

For normal queries, prefer `pool.query()`:

```js
export async function getUserById(id) {
  try {
    const result = await pool.query(
      'SELECT id, email FROM users WHERE id = $1',
      [id]
    )
    return result.rows[0] ?? null
  } catch (err) {
    console.error('Database query failed', {
      message: err.message,
      code: err.code,
    })
    throw err
  }
}
```

For transactions, always `release()` in `finally`:

```js
export async function createUser(email) {
  const client = await pool.connect()

  try {
    await client.query('BEGIN')
    const result = await client.query(
      'INSERT INTO users(email) VALUES($1) RETURNING id, email',
      [email]
    )
    await client.query('COMMIT')
    return result.rows[0]
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {})
    console.error('Transaction failed', {
      message: err.message,
      code: err.code,
    })
    throw err
  } finally {
    client.release()
  }
}
```

Shutdown cleanly:

```js
process.on('SIGTERM', async () => {
  await pool.end()
  process.exit(0)
})
```

